// @matrix 128x128

// @ramp linear 0:#081840 0.462:#01ff00 0.712:#7fceff
// Generated by Pattern Lab — Experiment (layer stack)
// Layers:
//   1. waves (scale 6, speed 0.1, angle 104°) @ 0.44
//   2. spiral (scale 11.5, speed 0.8, angle 58°) — difference @ 0.64
// Knobs: none bound — bind sliders to K1–K4 in the Experiment tab to control them live.
// Value field only: color comes from the Color Ramp panel.
// This is ordinary pattern code — send it to the Code tab and edit freely.

export function setup(params) {
  params.t = 0;
}

export function update(dt, input, params) {
  params.t += dt * 1.15;
}

export function draw(display, params, time) {
  const w = display.width;
  const h = display.height;
  const t = params.t;
  const s0 = 6;
  const sh0 = s0 * 0.5;
  const ph0 = t * 0.1;
  const a0 = 0.44;
  const ca0 = -0.2419;
  const sa0 = 0.9703;
  const s1 = 11.5;
  const sh1 = s1 * 0.5;
  const ph1 = t * 0.8;
  const a1 = 0.64;
  const ca1 = 0.5299;
  const sa1 = 0.848;
  const contrastV = 1.1;

  for (let y = 0; y < h; y++) {
    const ny = (y - h * 0.5) / h;
    for (let x = 0; x < w; x++) {
      const nx = (x - w * 0.5) / h;
      let v = 0;
      // layer 1: waves
      {
        const rx = nx * ca0 - ny * sa0;
        const ry = nx * sa0 + ny * ca0;
        const lv0 = 0.5 + 0.5 * Math.sin(rx * s0 + ph0);
        v = lv0 * a0;
      }
      // layer 2: spiral (difference)
      {
        const rx = nx * ca1 - ny * sa1;
        const ry = nx * sa1 + ny * ca1;
        const lv1 = 0.5 + 0.5 * Math.sin(Math.atan2(ry, rx) * 3 + Math.sqrt(rx * rx + ry * ry) * s1 - ph1);
        v = v + (Math.abs(v - lv1) - v) * a1;
      }
      v = (v - 0.5) * contrastV + 0.5;
      display.setValue(x, y, v);
    }
  }
}

